          method get() -> (uint64) {
              if (step.val == 0) {
                  return counter_start_value;
              }

              local cycles_t now = SIM_cycle_count(dev.obj);
              return (now - counter_start_time) / step.val
                  + counter_start_value;
          }

          method read() -> (uint64) {
              return get();
          }

          method restart() {
              counter_start_time = SIM_cycle_count(dev.obj);
              update_event();
